// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency) public {
        // Ensure the reference can handle the fuzz input
        vm.assume(sender != address(0));
        vm.assume(target != address(0));

        // Record address that should remain as DAO
        address expectedDAO = address(this);

        // Call the function
        (bool success, ) = address(c).call(abi.encodeWithSignature("assertGovernanceApproved(address,address,bool)", sender, target, emergency));

        // Rule: DAO must never be zero address
        assertTrue(c.DAO() != address(0), "DAO should not be zero");
    }
}

